44	  const { action, client_id: clientId, redirect_uri: redirectUri, state, code_challenge: codeChallenge, code_challenge_method: codeChallengeMethod, scope } = parsed.data;
45	
46	  console.log('[OAuth Consent] Action:', action, 'clientId:', clientId, 'redirectUri:', redirectUri);
